TRV.pack({"id":"unix_farma_c2","imgs":{},"questions":[{"id":"unix_farma_c2_q01","type":"mcq","topic":0,"diff":1,"hot":false,"q":"Despre farmacodinamie sunt adevărate:","opts":["Influențarea unor fenomene fizice (osmoza) sau chimice (reacții acido-bazice, redox) este un mecanism nespecific.","La nivel celular, medicamentul poate acționa pe membrană (enzime membranare, canale și pompe ionice), în citoplasmă, pe organite și în nucleu.","Studiază mecanismele de acțiune ale medicamentelor asupra biosistemelor la nivel molecular, celular, de organ și de organism.","Acționarea unor receptori specifici este un mecanism nespecific de acțiune.","Reflectă relația cauză → efect biologic."],"ok":[0,1,2,4],"why":"A – corect: E singurul mecanism nespecific din curs. B – corect: Nivelurile celulare enumerate în curs. C – corect: Definiția din curs. D – fals: E mecanism specific, alături de stimularea / inhibiția enzimatică, transportul specializat și sinteza proteică. E – corect: Parte din definiție.","src":"Curs UNIX Farmacologie · p. 34"},{"id":"unix_farma_c2_q02","type":"mcq","topic":0,"diff":1,"hot":false,"q":"Despre receptor, afinitate și activitate intrinsecă sunt adevărate:","opts":["Interacțiunea ligand-receptor este nesaturabilă și lipsită de stereospecificitate.","Activitatea intrinsecă este capacitatea complexului ligand-receptor de a stimula receptorul, prin modificări conformaționale, cu efect biologic.","Afinitatea este capacitatea complexului ligand-receptor de a stimula receptorul și de a produce efectul biologic.","Receptorul există într-o singură formă, cea activă (R*).","Receptorul este o structură macromoleculară proteică ce recunoaște și leagă specific un ligand la nivelul unui situs de legare."],"ok":[1,4],"why":"A – fals: Caracteristicile interacțiunii sunt tocmai saturabilitatea și stereospecificitatea (plus concurența pentru situs). B – corect: Definiția din curs. C – fals: Aceasta e activitatea intrinsecă; afinitatea e capacitatea ligandului de a se lega specific de situs. D – fals: Există în 2 forme: inactivă (R) și activă (R*). E – corect: Definiția receptorului.","src":"Curs UNIX Farmacologie · p. 35"},{"id":"unix_farma_c2_q03","type":"mcq","topic":1,"diff":1,"hot":true,"q":"Despre agonistul total sunt adevărate:","opts":["Se caracterizează prin CE50 sau pD2 (= −log CE50).","Este, prin definiție, un ligand de origine endogenă.","Se caracterizează prin parametrul pA2.","Are afinitate pentru receptor și activitate intrinsecă α = 1.","Produce un efect identic cu al mediatorului."],"ok":[0,3,4],"why":"A – corect: Parametrul agonistului. B – fals: Endogen e mediatorul; agonistul este exogen. C – fals: pA2 / pAx caracterizează antagonistul competitiv. D – corect: Rândul din tabelul liganzilor. E – corect: De aceea e „total”.","src":"Curs UNIX Farmacologie · p. 36"},{"id":"unix_farma_c2_q04","type":"mcq","topic":1,"diff":2,"hot":true,"q":"Despre antagonistul competitiv sunt adevărate:","opts":["Se leagă de același situs ca agonistul.","Produce un efect asemănător agonistului total, dar de intensitate mai mică.","Se leagă de un situs alosteric, diferit de al mediatorului.","Blocarea pe care o produce este reversibilă.","Are activitate intrinsecă nulă (α = 0)."],"ok":[0,3,4],"why":"A – corect: De aici numele: concurează pentru situs. B – fals: Aceasta descrie agonistul parțial; antagonistul competitiv blochează receptorul. C – fals: Situsul alosteric e al antagonistului necompetitiv. D – corect: Competitiv = reversibil; se depășește crescând agonistul. E – corect: Are afinitate, dar nu stimulează receptorul.","src":"Curs UNIX Farmacologie · p. 36, 55"},{"id":"unix_farma_c2_q05","type":"mcq","topic":1,"diff":2,"hot":true,"q":"Despre antagonistul necompetitiv sunt adevărate:","opts":["Efectul lui se depășește crescând suficient concentrația agonistului.","Se leagă de același situs ca agonistul și poate fi deplasat de acesta.","Se leagă de un alt situs (alosteric) decât agonistul.","Se caracterizează prin parametrul pD2'.","Se caracterizează prin parametrul pA2."],"ok":[2,3],"why":"A – fals: Fiind ireversibil, oricât agonist ai da, o parte din receptori rămân scoși din joc. B – fals: Se leagă de alt situs (alosteric), ireversibil. C – corect: Rândul din tabelul liganzilor. D – corect: pD2' = −log din concentrația care scade la jumătate efectul agonistului. E – fals: pA2 e al antagonistului competitiv; necompetitivul are pD2'.","src":"Curs UNIX Farmacologie · p. 36–37"},{"id":"unix_farma_c2_q06","type":"mcq","topic":1,"diff":2,"hot":true,"q":"Despre agonistul parțial sunt adevărate:","opts":["Produce un efect asemănător agonistului total, dar nu atinge maximul la nicio doză.","Are afinitate pentru receptor.","Are activitate intrinsecă între 0 și 1 (0 < α < 1).","Dacă i se crește suficient doza, atinge efectul maxim al agonistului total.","În prezența unui agonist total, se comportă ca un antagonist competitiv."],"ok":[0,1,2,4],"why":"A – corect: Definiția din curs. B – corect: Toți liganzii exogeni din tabel au afinitate. C – corect: De aceea e „parțial”. D – fals: Capcană UNIX: nu atinge maximul la nicio doză. E – corect: Ocupă receptorii și produce un efect mai mic decât ar fi produs agonistul total.","src":"Curs UNIX Farmacologie · p. 36–37, 55"},{"id":"unix_farma_c2_q07","type":"mcq","topic":1,"diff":3,"hot":true,"q":"Despre agonistul invers sunt adevărate:","opts":["Trece receptorii din forma activă (R*) în forma inactivă (R).","Este, de fapt, un antagonist competitiv.","Are activitate intrinsecă negativă (α < 0).","Produce un efect opus celui al mediatorului.","Efectul lui nu poate fi antagonizat de un antagonist competitiv."],"ok":[0,2,3],"why":"A – corect: De aici efectul opus mediatorului. B – fals: Capcană UNIX: are activitate intrinsecă negativă, pe când antagonistul competitiv are α = 0. C – corect: Rândul din tabelul liganzilor. D – corect: Consecința trecerii R* → R. E – fals: Cursul spune exact invers: e antagonizat de un antagonist competitiv.","src":"Curs UNIX Farmacologie · p. 36, 55"},{"id":"unix_farma_c2_q08","type":"mcq","topic":2,"diff":2,"hot":true,"q":"Pe curbele doză-efect (efectul în funcție de log doză) sunt adevărate:","opts":["Antagonistul necompetitiv deplasează curba agonistului la stânga, cu același maxim.","În prezența unui antagonist necompetitiv, efectul maxim al agonistului scade.","În prezența unui antagonist competitiv, curba agonistului total se deplasează la dreapta, paralel.","Curba agonistului parțial atinge același maxim ca a agonistului total, doar la doze mai mari.","Antagonistul competitiv nu modifică efectul maxim al agonistului total."],"ok":[1,2,4],"why":"A – fals: Antagonistul necompetitiv scade maximul. B – corect: O parte din receptori sunt scoși din joc ireversibil. C – corect: E nevoie de mai mult agonist pentru același efect. D – fals: Agonistul parțial are maxim mai mic. E – corect: Același maxim, atins la doze mai mari.","src":"Curs UNIX Farmacologie · p. 37"},{"id":"unix_farma_c2_q09","type":"mcq","topic":2,"diff":3,"hot":true,"q":"Despre parametrii farmacodinamici sunt adevărate:","opts":["pA2 = −log din concentrația de antagonist care scade la jumătate efectul agonistului.","pA2 = −log din concentrația molară de antagonist care face necesară dublarea concentrației de agonist pentru același efect.","pD2' este parametrul care caracterizează agonistul parțial.","pD2' = −log din concentrația molară de antagonist necompetitiv care scade la jumătate efectul agonistului.","pD2 caracterizează antagonistul competitiv."],"ok":[1,3],"why":"A – fals: Aceasta e definiția lui pD2' (antagonist necompetitiv). B – corect: Definiția din curs (pAx: creșterea de x ori). C – fals: pD2' e al antagonistului necompetitiv; în tabel, agonistul parțial nu are parametru propriu. D – corect: Definiția din curs. E – fals: pD2 (= −log CE50) caracterizează agonistul.","src":"Curs UNIX Farmacologie · p. 36–37"},{"id":"unix_farma_c2_q10","type":"mcq","topic":2,"diff":3,"hot":true,"q":"Ce explică forma curbelor doză-efect în prezența antagoniștilor?","opts":["Antagonistul competitiv, ocupând reversibil același situs, este „dat afară” de excesul de agonist.","Antagonistul competitiv scade efectul maxim al agonistului total.","Antagonistul necompetitiv scoate din joc o parte din receptori, oricât agonist s-ar administra.","În prezența unui antagonist necompetitiv, efectul maxim se reface prin creșterea dozei de agonist.","Antagonistul competitiv blochează ireversibil o fracțiune din receptori, de aceea scade efectul maxim."],"ok":[0,2],"why":"A – corect: De aceea maximul se poate atinge din nou. B – fals: Curba se mută la dreapta, paralel, cu același maxim. C – corect: Legare alosterică, ireversibilă → maxim scăzut. D – fals: Maximul rămâne scăzut; se reface doar în cazul antagonistului competitiv. E – fals: Competitivul e reversibil și nu scade maximul; asta descrie necompetitivul.","src":"Curs UNIX Farmacologie · p. 37"},{"id":"unix_farma_c2_q11","type":"mcq","topic":3,"diff":2,"hot":false,"q":"Despre receptorii cuplați cu proteine G sunt adevărate:","opts":["Subunitățile βγ, legate de GTP, migrează intracelular și activează enzima efectoare.","Sunt receptori monomerici care traversează membrana de 7 ori („în serpentină”).","Proteina G cuplată este trimerică (αβγ) și GTP-dependentă.","Subunitățile βγ sunt comune tuturor proteinelor G.","Receptorul și efectorul se află în aceeași moleculă."],"ok":[1,2,3],"why":"A – fals: Subunitatea α (cu GTP) migrează intracelular. B – corect: 7 helixuri transmembranare. C – corect: Structura din curs. D – corect: Subtipurile diferă prin subunitatea α (αs, αi, αq, αt, αo). E – fals: Aceasta e caracteristica receptorilor tirozin-kinazici.","src":"Curs UNIX Farmacologie · p. 40"},{"id":"unix_farma_c2_q12","type":"mcq","topic":3,"diff":1,"hot":true,"q":"Despre efectele proteinelor G sunt adevărate:","opts":["Gq activează adenilat-ciclaza și crește AMPc.","Gq crește activitatea fosfolipazei C, care hidrolizează PIP2 în IP3 și DAG.","Gt acționează pe canale ionice, iar Go sunt transducinele implicate în vedere.","Gs inhibă adenilat-ciclaza și scade AMPc.","Gi scade activitatea adenilat-ciclazei → ↓ AMPc."],"ok":[1,4],"why":"A – fals: Gq acționează pe fosfolipaza C, nu pe adenilat-ciclază. B – corect: Calea fosfatidil-inozitidică. C – fals: Invers: Gt = transducine (vedere), Go = canale ionice. D – fals: Gs crește activitatea adenilat-ciclazei → ↑ AMPc. E – corect: I = inhibitory.","src":"Curs UNIX Farmacologie · p. 40–41"},{"id":"unix_farma_c2_q13","type":"mcq","topic":3,"diff":2,"hot":true,"q":"Sunt cuplați cu proteine Gi:","opts":["Receptorii M3 din musculatura netedă digestivă.","Receptorii opioizi µ din SNC.","Receptorii β2-adrenergici presinaptici.","Receptorii α2-adrenergici presinaptici.","Receptorii M2-colinergici din cord."],"ok":[1,3,4],"why":"A – fals: M1 și M3 sunt cuplați cu Gq. B – corect: Exemplul din curs pentru Gi. C – fals: Toți receptorii β, indiferent de localizare, sunt Gs. D – corect: Gi → ↓ AMPc. E – corect: Capcană UNIX: M2 = Gi, nu Gq.","src":"Curs UNIX Farmacologie · p. 41, 55"},{"id":"unix_farma_c2_q14","type":"mcq","topic":3,"diff":1,"hot":true,"q":"Sunt cuplați cu proteine Gq:","opts":["Receptorii α1 din mușchiul radial al irisului.","Receptorii M3 din musculatura netedă bronșică.","Receptorii α1 postsinaptici din musculatura netedă vasculară.","Receptorii H2-histaminergici din celulele parietale gastrice.","Receptorii M1 / M3 din mușchiul circular și din mușchiul ciliar al irisului."],"ok":[0,1,2,4],"why":"A – corect: Exemplul din curs. B – corect: M1 și M3 = Gq. C – corect: α1 = Gq. D – fals: H2 sunt cuplați cu Gs. E – corect: Exemplul din curs.","src":"Curs UNIX Farmacologie · p. 41"},{"id":"unix_farma_c2_q15","type":"mcq","topic":3,"diff":3,"hot":true,"q":"Aplicând cuplarea receptorilor cu proteinele G, sunt adevărate:","opts":["Receptorii β3 sunt cuplați cu Gi.","Blocarea receptorilor postsinaptici cuplați cu Gq (α1) din vase produce vasodilatație.","Toți receptorii β (β1, β2, β3) sunt cuplați cu Gs, indiferent dacă sunt pre- sau postsinaptici.","Cardioinhibiția se obține prin blocarea receptorilor α din cord.","Blocarea receptorilor cuplați cu Gs (β2) poate produce bronhoconstricție."],"ok":[1,2,4],"why":"A – fals: Toți receptorii β sunt Gs. B – corect: Afirmație dată ca adevărată în curs. C – corect: Regula „β sunt toți s”. D – fals: Cordul are receptori β1, cuplați cu Gs. E – corect: β2 (Gs) → AMPc → bronhodilatație; blocarea lor are efect opus.","src":"Curs UNIX Farmacologie · p. 41"},{"id":"unix_farma_c2_q16","type":"mcq","topic":3,"diff":1,"hot":false,"q":"Despre receptorii cuplați cu canale ionice sunt adevărate:","opts":["Receptorii GABA-A sunt cuplați cu canale de Cl⁻ → hiperpolarizare → PPSI.","Legarea agonistului produce deschiderea sau închiderea canalului asociat.","Receptorii 5-HT3 sunt cuplați cu canale de Na⁺.","Receptorii N-colinergici sunt cuplați cu proteine G.","Receptorii N-colinergici (N1, N2) sunt cuplați cu canale de Na⁺ → depolarizare → PPSE."],"ok":[0,1,2,4],"why":"A – corect: Efect inhibitor. B – corect: Mecanismul din curs. C – corect: Exemplul din curs. D – fals: Capcană UNIX: sunt cuplați cu canale de Na⁺. E – corect: Sunt ionotropi.","src":"Curs UNIX Farmacologie · p. 42, 55"},{"id":"unix_farma_c2_q17","type":"mcq","topic":3,"diff":2,"hot":false,"q":"Despre receptorii cu acțiune tirozin-kinazică sunt adevărate:","opts":["Exemple: receptorii pentru insulină, GH și HER-2.","Traversează membrana de 7 ori.","Receptorul insulinei este cuplat cu proteine G.","Domeniul enzimatic tirozin-kinazic este extracelular.","Receptorul și efectorul se află în aceeași moleculă (receptori-enzime)."],"ok":[0,4],"why":"A – corect: Exemplele din curs. B – fals: În general au un singur helix transmembranar; 7 helixuri au receptorii cuplați cu proteine G. C – fals: Capcană UNIX: e receptor tirozin-kinazic. D – fals: Domeniul enzimatic e intracitoplasmatic. E – corect: Domeniul extracelular leagă ligandul, cel intracitoplasmatic e tirozin-kinaza.","src":"Curs UNIX Farmacologie · p. 42, 55"},{"id":"unix_farma_c2_q18","type":"mcq","topic":4,"diff":1,"hot":false,"q":"Despre receptorii nucleari (citosolici) sunt adevărate:","opts":["Receptorii estrogenici ERα și ERβ sunt receptori nucleari.","Agoniștii lor sunt hidrosolubili și se leagă de un domeniu extracelular.","Complexul agonist-receptor intră în nucleu, se leagă de ADN și modifică transcripția → proteine specifice.","În forma inactivă, receptorul citosolic este legat de proteine de șoc termic (HSP), pe care agonistul le desprinde.","Agoniștii lor (steroizi, hormoni tiroidieni, retinoizi) sunt lipofili și trec ușor membrana."],"ok":[0,2,3,4],"why":"A – corect: Exemplul din curs. B – fals: Sunt lipofili și se leagă de receptorul citosolic. C – corect: ARNm → translație ribozomală. D – corect: Mecanismul din curs. E – corect: De aceea receptorul poate fi intracelular.","src":"Curs UNIX Farmacologie · p. 43"},{"id":"unix_farma_c2_q19","type":"mcq","topic":4,"diff":2,"hot":false,"q":"Despre receptorii nucleari și glucocorticoizi sunt adevărate:","opts":["Hormonii tiroidieni și vitamina D acționează pe receptori nemembranari.","Glucocorticoizii favorizează sinteza anexinei A1 (lipocortina / lipomodulina).","Anexina A1 stimulează fosfolipaza C.","Inhibarea fosfolipazei A2 blochează cascada acidului arahidonic, de unde efectul antiinflamator.","Există receptori nucleari pentru retinoizi (RXR, RAR)."],"ok":[0,1,3,4],"why":"A – corect: Receptorii nemembranari: steroizi, hormoni tiroidieni, vitaminele A și D. B – corect: Exemplul din curs. C – fals: Anexina A1 inhibă fosfolipaza A2. D – corect: Lanțul din curs. E – corect: Exemplu din curs.","src":"Curs UNIX Farmacologie · p. 39, 43"},{"id":"unix_farma_c2_q20","type":"mcq","topic":5,"diff":2,"hot":true,"q":"Creșterea AMPc în mușchiul neted (ex. bronhii prin β2) produce:","opts":["Bronhoconstricție.","Sechestrarea Ca²⁺ în depozite prin calsechestrină → ↓ Ca²⁺ intracelular → relaxare.","Activarea protein-kinazei A (PKA).","Fosforilarea Ca²⁺-ATP-azei, care scoate Ca²⁺ → ↓ Ca²⁺ intracelular.","Fosforilarea calciductinei, care deschide canalele de Ca²⁺."],"ok":[1,2,3],"why":"A – fals: Capcană UNIX: creșterea AMPc relaxează musculatura netedă (bronhodilatație). B – corect: A doua cale de scădere a Ca²⁺. C – corect: β2 (Gs) → ↑ AC → ↑ AMPc → ↑ PKA. D – corect: Una dintre căile de scădere a Ca²⁺. E – fals: Calciductina e mecanismul din cord, unde AMPc contractă.","src":"Curs UNIX Farmacologie · p. 44, 55"},{"id":"unix_farma_c2_q21","type":"mcq","topic":5,"diff":3,"hot":true,"q":"De ce același AMPc contractă cordul, deși relaxează mușchiul neted?","opts":["Calciductina deschide canalele de Ca²⁺ și eliberează Ca²⁺ din depozite → contracție.","Receptorii β1 din cord sunt cuplați cu Gi.","În cord, creșterea AMPc relaxează miocardul, ca în mușchiul neted.","În cord, AMPc activează Ca²⁺-ATP-aza și calsechestrina, crescând Ca²⁺ intracelular.","În cord, β1 (Gs) → ↑ AMPc → ↑ PKA → fosforilarea calciductinei."],"ok":[0,4],"why":"A – corect: ↑ Ca²⁺ intracelular → contracție. B – fals: Toți receptorii β sunt cuplați cu Gs. C – fals: În cord AMPc contractă (calciductina). D – fals: Ca²⁺-ATP-aza și calsechestrina scad Ca²⁺; ele explică relaxarea mușchiului neted. E – corect: Lanțul pe cord.","src":"Curs UNIX Farmacologie · p. 44"},{"id":"unix_farma_c2_q22","type":"mcq","topic":5,"diff":2,"hot":true,"q":"Sunt efecte ale creșterii AMPc, conform cursului:","opts":["Lipoliza și glicogenoliza, prin fosforilarea enzimelor.","Contracția musculaturii netede vasculare.","Hipersecreția glandelor exocrine.","Influențarea transcripției genice.","În nodul sinusal, activarea canalelor HCN → depolarizare → creșterea frecvenței cardiace."],"ok":[0,2,3,4],"why":"A – corect: Efect listat în curs. B – fals: AMPc relaxează mușchiul neted (vase, bronhii, uter). C – corect: Efect listat în curs. D – corect: Efect listat în curs. E – corect: Efect listat în curs.","src":"Curs UNIX Farmacologie · p. 44"},{"id":"unix_farma_c2_q23","type":"mcq","topic":5,"diff":2,"hot":false,"q":"Despre calea IP3 / DAG sunt adevărate:","opts":["DAG eliberează Ca²⁺ din reticulul endoplasmic și produce contracția fazică.","IP3 eliberează Ca²⁺ din reticulul endoplasmic → contracție fazică.","DAG activează protein-kinaza C → contracție tonică, care menține răspunsul.","Receptorii M1, M3 și α1 → Gq → ↑ fosfolipaza C → PIP2 → IP3 + DAG.","Adrenalina pe receptorii α1 vasculari produce vasodilatație prin IP3 + DAG."],"ok":[1,2,3],"why":"A – fals: Ca²⁺ din RE îl eliberează IP3; DAG activează PKC (contracția tonică). B – corect: Schema din curs. C – corect: Schema din curs. D – corect: Calea fosfatidil-inozitidică. E – fals: ↑ IP3 + DAG → ↑ Ca²⁺ → vasoconstricție; vasodilatația vine de la un antagonist α1.","src":"Curs UNIX Farmacologie · p. 45"},{"id":"unix_farma_c2_q24","type":"mcq","topic":5,"diff":2,"hot":false,"q":"Despre calea NO – GMPc sunt adevărate:","opts":["În endoteliu, NO-sintaza formează NO din arginină.","NO activează adenilat-ciclaza membranară din mușchiul neted.","GMPc produce vasoconstricție.","GMPc se formează din ATP.","NO difuzează în mușchiul neted și activează guanilat-ciclaza solubilă → GTP → GMPc → efect miorelaxant (vasodilatație)."],"ok":[0,4],"why":"A – corect: Începutul căii. B – fals: NO activează guanilat-ciclaza solubilă. C – fals: Efectul este miorelaxant (vasodilatație). D – fals: GMPc se formează din GTP, sub acțiunea guanilat-ciclazei. E – corect: Lanțul din curs.","src":"Curs UNIX Farmacologie · p. 45"},{"id":"unix_farma_c2_q25","type":"mcq","topic":6,"diff":2,"hot":true,"q":"Despre turnover-ul receptorilor sunt adevărate:","opts":["Receptorii se formează direct în membrană, fără comandă genică.","Excesul cronic de agonist produce down-regulation (scade numărul de receptori) → toleranță.","Receptorii internalizați nu mai pot fi stimulați de mediator sau de agonist.","Excesul cronic de antagonist produce up-regulation; la oprirea bruscă apare rebound (ex. β-blocantele).","Administrarea cronică a unui antagonist scade numărul de receptori."],"ok":[1,2,3],"why":"A – fals: Sunt proteine sintetizate în ribozomi, sub comanda unor gene nucleare, apoi transportate la membrană. B – corect: Reglarea prin exces cronic. C – corect: Ciclul de viață al receptorilor. D – corect: De aceea β-blocantul nu se oprește brusc. E – fals: Antagonistul cronic produce up-regulation (crește numărul de receptori).","src":"Curs UNIX Farmacologie · p. 46"},{"id":"unix_farma_c2_q26","type":"mcq","topic":6,"diff":1,"hot":true,"q":"Despre reglarea numărului de receptori sunt adevărate:","opts":["Down-regulation înseamnă creșterea numărului de receptori.","Hormonii tiroidieni cresc numărul receptorilor β1-adrenergici, de aceea hipertiroidianul e tahicard.","Estrogenii cresc numărul receptorilor pentru oxitocină.","Densitatea receptorilor opioizi nu depinde de concentrația ionilor.","Hormonii tiroidieni scad numărul receptorilor β1-adrenergici, de unde bradicardia hipertiroidianului."],"ok":[1,2],"why":"A – fals: Down-regulation = scade numărul de receptori. B – corect: Mecanismul umoral. C – corect: Mecanismul umoral. D – fals: E exemplul din curs pentru mecanismul ionic: densitatea se modifică în funcție de concentrația ionilor. E – fals: Cresc numărul receptorilor β1 → hipertiroidianul e tahicard.","src":"Curs UNIX Farmacologie · p. 46"},{"id":"unix_farma_c2_q27","type":"mcq","topic":7,"diff":1,"hot":false,"q":"Despre sinergismul medicamentos sunt adevărate:","opts":["Potențarea (sinergism supraaditiv): E(AB) > E(A) + E(B).","Co-trimoxazolul (sulfametoxazol + trimetoprim) este un exemplu de sinergism aditiv.","Sinergismul aditiv: E(AB) ≈ E(A) + E(B), ex. aspirină + paracetamol.","Neuroleptanalgezia (fentanil + droperidol) este un exemplu de potențare.","Amoxicilina + acidul clavulanic este un exemplu de potențare."],"ok":[0,2,3,4],"why":"A – corect: Definiția din curs. B – fals: Co-trimoxazolul e exemplu de potențare (supraaditiv). C – corect: Asocierile analgezice. D – corect: Exemplul din curs. E – corect: Penicilină + inhibitor de β-lactamază.","src":"Curs UNIX Farmacologie · p. 48"},{"id":"unix_farma_c2_q28","type":"mcq","topic":7,"diff":2,"hot":false,"q":"Despre antagonismul medicamentos sunt adevărate:","opts":["CN⁻ + edetat cobaltic este un exemplu de antagonism chimic.","Antagonismul chimic: metalele grele neutralizate sau complexate de EDTA.","Cu²⁺ + D-penicilamină este un exemplu de antagonism chimic.","Antagonismul funcțional înseamnă două substanțe care se leagă de același receptor.","Antagonismul fizic: adsorbția la suprafață (cărbune activ + alcaloizi)."],"ok":[0,1,2,4],"why":"A – corect: Neutralizare de către un antidot. B – corect: Antidot chimic. C – corect: Complexare de către antidot. D – fals: Funcțional = efecte opuse prin mecanisme diferite (deprimante + excitante centrale); același receptor = antagonism farmacologic. E – corect: Exemplul din curs.","src":"Curs UNIX Farmacologie · p. 48"},{"id":"unix_farma_c2_q29","type":"mcq","topic":7,"diff":3,"hot":false,"q":"Despre clasificarea interacțiunilor medicamentoase sunt adevărate:","opts":["Antagonismul farmacologic competitiv: același receptor, reciproc complet, reversibil, specific; se caracterizează prin pA2.","Sinergismul și antagonismul sunt interacțiuni farmacocinetice.","Antagonismul farmacologic necompetitiv este reversibil și se caracterizează prin pA2.","Deplasarea de pe proteinele plasmatice și inducția / inhibiția enzimatică sunt interacțiuni farmacocinetice.","Asocierea alcool + deprimante centrale este un exemplu de antagonism funcțional."],"ok":[0,3],"why":"A – corect: Rândul din curs. B – fals: Sunt interacțiuni farmacodinamice. C – fals: Necompetitivul e alosteric sau pe altă verigă, ireversibil, cu pD2'. D – corect: Distribuție, respectiv metabolizare. E – fals: E exemplu de potențare (sinergism supraaditiv).","src":"Curs UNIX Farmacologie · p. 47–48"},{"id":"unix_farma_c2_q30","type":"mcq","topic":8,"diff":1,"hot":false,"q":"Despre definițiile din farmacotoxicologie sunt adevărate:","opts":["Reacția adversă apare numai la supradozaj.","Efectul secundar este consecința indirectă a acțiunii terapeutice, strict dependentă de mecanismul de acțiune.","Evenimentul advers este, obligatoriu, în relație directă cu medicația.","Reacția adversă este o manifestare nedorită, nocivă, după medicamente date la doze terapeutice.","Efectul toxic este consecința acțiunii directe a medicamentului asupra unui organ."],"ok":[1,3,4],"why":"A – fals: Apare la doze terapeutice (profilactic, curativ, diagnostic). B – corect: Definiția din curs. C – fals: Evenimentul advers poate fi sau nu în relație directă cu medicația. D – corect: Definiția din curs. E – corect: Definiția din curs.","src":"Curs UNIX Farmacologie · p. 49"},{"id":"unix_farma_c2_q31","type":"mcq","topic":8,"diff":1,"hot":false,"q":"Despre intoleranță și toleranță sunt adevărate:","opts":["Toleranța este un răspuns diminuat la doza terapeutică.","Intoleranța este un răspuns exagerat la doza terapeutică.","Alergia este o intoleranță dobândită.","Idiosincrazia este o intoleranță dobândită.","Idiosincrazia este o intoleranță înnăscută, condiționată genetic."],"ok":[0,1,2,4],"why":"A – corect: Cealaltă extremă a curbei. B – corect: Extrema curbei Gauss. C – corect: Definiția din curs. D – fals: Intoleranța dobândită este alergia. E – corect: Definiția din curs.","src":"Curs UNIX Farmacologie · p. 49"},{"id":"unix_farma_c2_q32","type":"mcq","topic":8,"diff":1,"hot":false,"q":"Despre reacțiile alergice de tip I și II sunt adevărate:","opts":["Tipul I: IgE fixate pe mastocite → eliberare de histamină, leucotriene, PG, PAF.","Tipul II: medicamentul se leagă de proteinele celulare → IgG, IgM + complement → liză celulară.","Edemul Quincke este o reacție de tip II (citotoxic).","Tipul II este mediat de limfocite T sensibilizate.","Tipul I apare în 2–5 minute până la 1–2 ore."],"ok":[0,1,4],"why":"A – corect: Mecanismul anafilactic. B – corect: Mecanismul citotoxic. C – fals: Edemul Quincke e exemplu de tip I. D – fals: Mediat celular, prin limfocite T, este tipul IV. E – corect: Intervalul din curs.","src":"Curs UNIX Farmacologie · p. 50"},{"id":"unix_farma_c2_q33","type":"mcq","topic":8,"diff":3,"hot":false,"q":"Sunt exemple de reacții alergice de tip II (citotoxic), conform cursului:","opts":["Anemia hemolitică la peniciline și metildopa.","Dermatita de contact.","Agranulocitoza la cloramfenicol, sulfonamide, săruri de aur, clozapină.","Sindromul lupoid la hidralazină, procainamidă, izoniazidă.","Anemia aplastică la cloramfenicol."],"ok":[0,2,3,4],"why":"A – corect: Exemplu din curs. B – fals: E reacție de tip IV (întârziat, mediat celular). C – corect: Exemplu din curs. D – corect: Exemplu din curs. E – corect: Exemplu din curs.","src":"Curs UNIX Farmacologie · p. 50"},{"id":"unix_farma_c2_q34","type":"mcq","topic":8,"diff":2,"hot":false,"q":"Despre reacțiile alergice de tip III și IV sunt adevărate:","opts":["Glomerulonefrita și vasculita medicamentoasă sunt reacții de tip IV.","Boala serului este o reacție de tip III și apare la 1–3 săptămâni.","Tipul III: complexe Ag-Ac → complement → obstrucția vaselor mici → inflamație.","Boala serului este o reacție de tip I, care apare în câteva minute.","Tipul IV este mediat de IgE fixate pe mastocite."],"ok":[1,2],"why":"A – fals: Sunt exemple de tip III (complexe imune). B – corect: Capcană UNIX: nu e tip I și nu apare în minute. C – corect: Mecanismul din curs. D – fals: E tip III, la 1–3 săptămâni. E – fals: Tipul IV e mediat celular (limfocite T sensibilizate); IgE = tipul I.","src":"Curs UNIX Farmacologie · p. 50, 55"},{"id":"unix_farma_c2_q35","type":"mcq","topic":8,"diff":3,"hot":false,"q":"Comparând reacțiile alergice, idiosincrazice și toxice, sunt adevărate:","opts":["Reacția toxică este corelată cu doza și are specificitate de organ.","Reacția anafilactoidă: medicamentul (ex. dextranii) degranulează direct mastocitele, fără anticorpi.","Reacția anafilactoidă este mediată de IgE.","Reacția alergică este independentă de doză și apare la re-expunere.","Reacția idiosincrazică este dependentă de doză."],"ok":[0,1,3],"why":"A – corect: Mecanism toxic direct. B – corect: De aceea nu e alergie propriu-zisă. C – fals: Apare fără anticorpi. D – corect: Medicamentul / metabolitul devine antigenic. E – fals: Capcană UNIX: alergicele și idiosincrazicele sunt independente de doză.","src":"Curs UNIX Farmacologie · p. 51, 55"},{"id":"unix_farma_c2_q36","type":"mcq","topic":8,"diff":1,"hot":false,"q":"Sunt date în curs ca exemple de idiosincrazie:","opts":["Hipertermia malignă.","Apneea toxică la suxametoniu, prin deficit de pseudocolinesterază.","Hemoliza prin deficit de G6PD.","Necroza hepatică doză-dependentă la paracetamol.","Polimorfismul acetiltransferazelor."],"ok":[0,1,2,4],"why":"A – corect: Exemplu din curs. B – corect: Exemplu din curs. C – corect: Exemplu din curs. D – fals: E reacție toxică (corelată cu doza). E – corect: Exemplu din curs; idiosincraziile caracterizează un grup de populație (distribuție polimodală).","src":"Curs UNIX Farmacologie · p. 51"},{"id":"unix_farma_c2_q37","type":"mcq","topic":8,"diff":2,"hot":false,"q":"Despre reacțiile toxice sunt adevărate:","opts":["Neurolepticele produc polinevrite.","Indexul terapeutic = DE50 / DL50.","Teratogenitatea, carcinogenitatea și mutagenitatea nu fac parte din reacțiile toxice.","Paracetamolul și metotrexatul produc necroză hepatică doză-dependentă.","Indexul terapeutic = DL50 / DE50."],"ok":[3,4],"why":"A – fals: Neurolepticele → diskinezie tardivă; polinevritele: izoniazidă, etambutol, metronidazol. B – fals: Raportul e invers: DL50 / DE50. C – fals: Sunt tipuri speciale de reacții toxice. D – corect: Exemplu din curs. E – corect: Formula din curs.","src":"Curs UNIX Farmacologie · p. 51"},{"id":"unix_farma_c2_q38","type":"mcq","topic":8,"diff":2,"hot":false,"q":"Despre riscurile medicamentelor în sarcină sunt adevărate:","opts":["Riscul malformativ (teratogen) apare în perioada embrionară (organogeneza), în trimestrul I.","Riscul fetal înseamnă efecte teratogene apărute în trimestrele II–III.","Riscul teratogen este maxim în trimestrul III.","Teratogeneza directă: citostatice, antitiroidiene, retinoizi.","Riscul tardiv înseamnă afectarea capacităților cognitive și psihomotorii și carcinogenitate."],"ok":[0,3,4],"why":"A – corect: Tabelul din curs. B – fals: Riscul fetal = agresiune funcțională (efecte toxice, nu teratogene). C – fals: În trimestrele II–III organogeneza e terminată; riscul e fetal (toxic, nu teratogen). D – corect: Exemplele din curs. E – corect: Tabelul din curs.","src":"Curs UNIX Farmacologie · p. 52"},{"id":"unix_farma_c2_q39","type":"mcq","topic":8,"diff":2,"hot":true,"q":"Despre mecanismele toleranței sunt adevărate:","opts":["Toleranța apare prin întreruperea bruscă a unui agonist.","Inactivarea receptorilor prin fosforilare este un mecanism al toleranței.","Toleranța apare prin administrarea prelungită a unui antagonist.","Toleranța farmacocinetică apare prin autoinducție enzimatică.","Down-regulation / internalizarea receptorilor duce la toleranță cronică (după săptămâni–luni)."],"ok":[1,3,4],"why":"A – fals: Variantă de la sumativ: întreruperea bruscă dă sevraj. B – corect: Mecanism farmacodinamic. C – fals: Variantă de la sumativ: antagonistul prelungit dă up-regulation, nu toleranță. D – corect: Mecanismul farmacocinetic. E – corect: Mecanism farmacodinamic.","src":"Curs UNIX Farmacologie · p. 53"},{"id":"unix_farma_c2_q40","type":"mcq","topic":8,"diff":3,"hot":true,"q":"Despre tahifilaxie și dependență sunt adevărate:","opts":["Tahifilaxia se produce prin autoinducție enzimatică.","Dependența psihică se definește prin apariția sindromului de abstinență la întrerupere.","Dependența fizică: modificări adaptative prin contrareglare; la întrerupere apare sindromul de abstinență.","Tahifilaxia este o toleranță cronică, prin down-regulation.","Tahifilaxia apare la doze repetate la intervale scurte, prin epuizarea mediatorilor (ex. efedrina, decongestionantele nazale)."],"ok":[2,4],"why":"A – fals: Autoinducția e mecanismul toleranței farmacocinetice. B – fals: Dependența psihică = constrângerea de a consuma substanța pentru satisfacție emoțională; abstinența ține de dependența fizică. C – corect: Definiția din curs. D – fals: Capcană UNIX: tahifilaxia e acută, prin epuizarea mediatorilor. E – corect: Toleranța acută.","src":"Curs UNIX Farmacologie · p. 53, 55"},{"id":"unix_farma_c2_q41","type":"mcq","topic":8,"diff":2,"hot":false,"q":"Despre clasificarea reacțiilor adverse A–F sunt adevărate:","opts":["Tipul B (bizarre): doză-independent, impredictibil; include reacțiile alergice și idiosincrazice.","Tipul D (delayed): lipsa efectului terapeutic prin neaderență sau medicament neconform.","Tipul C (chronic): după expunere îndelungată, ex. nefropatia analgezică, diskinezia tardivă.","Tipul A (augmented): doză-dependent, predictibil, legat de mecanismul de acțiune (ex. hipotensiune ortostatică, hipoglicemie).","Tipul E (ending of dose): efect rebound la β-blocante, insuficiență glandulară la corticoizi."],"ok":[0,2,3,4],"why":"A – corect: Tabelul din curs. B – fals: Aceasta e tipul F (failure of treatment); D = reacții apărute la ani după expunere. C – corect: Tabelul din curs. D – corect: Tabelul din curs. E – corect: Apar la întreruperea bruscă.","src":"Curs UNIX Farmacologie · p. 54"},{"id":"unix_farma_c2_q42","type":"mcq","topic":8,"diff":3,"hot":false,"q":"Tot despre clasificarea A–F, sunt adevărate:","opts":["Reacțiile de tip B sunt frecvente și ușoare.","Reacțiile de tip D apar la ani după expunere, ex. carcinogeneza la estrogeni.","Reacțiile de tip A sunt frecvente, ușoare sau medii.","Reacțiile de tip C sunt, în general, reversibile.","Tipul F înseamnă lipsa de efect terapeutic (neaderență, medicament neconform, defect genetic)."],"ok":[1,2,4],"why":"A – fals: Tipul B e rar și poate fi sever; frecvente și ușoare / medii sunt cele de tip A. B – corect: Tabelul din curs. C – corect: Tabelul din curs. D – fals: Sunt, în general, ireversibile. E – corect: Failure of treatment.","src":"Curs UNIX Farmacologie · p. 54"},{"id":"unix_farma_c2_cs01","type":"mcq","topic":0,"diff":1,"hot":false,"q":"Afinitatea pentru receptor este:","opts":["Capacitatea ligandului (mediator, medicament) de a se lega specific de situsul de legare al receptorului.","Capacitatea complexului ligand-receptor de a stimula receptorul, prin modificări conformaționale, cu efect biologic.","Numărul de receptori ai unei celule, reglat prin up- și down-regulation.","Relația lineară dintre legarea specifică și concentrația tisulară."],"ok":[0],"why":"A – corect: așa definește cursul afinitatea (legarea specifică de situs). B – fals: aceasta este activitatea intrinsecă. C – fals: numărul de receptori ține de turnover (densitatea receptorilor), nu de afinitate. D – fals: este una dintre caracteristicile interacțiunii ligand-receptor, nu definiția afinității.","src":"Curs UNIX Farmacologie · p. 35"},{"id":"unix_farma_c2_cs02","type":"mcq","topic":0,"diff":2,"hot":false,"q":"Este o caracteristică a interacțiunii ligand-receptor, conform cursului:","opts":["Capacitatea de legare nelimitată (interacțiune nesaturabilă).","Independența legării față de configurația spațială a ligandului.","Concurența pentru situsul de legare: compușii cu structură asemănătoare se deplasează reciproc.","Absența oricărei relații între legarea specifică și concentrația tisulară."],"ok":[2],"why":"C – corect: concurența pentru situs este una dintre cele 4 caracteristici din curs. A – fals: interacțiunea este saturabilă. B – fals: interacțiunea este stereospecifică (depinde de configurația spațială). D – fals: cursul descrie o relație lineară între legarea specifică și concentrația tisulară.","src":"Curs UNIX Farmacologie · p. 35"},{"id":"unix_farma_c2_cs03","type":"mcq","topic":1,"diff":1,"hot":true,"q":"Ligandul exogen care are afinitate pentru receptor, nu are activitate intrinsecă (α = 0) și se leagă de același situs ca mediatorul este:","opts":["Agonistul parțial.","Antagonistul competitiv.","Agonistul invers.","Antagonistul necompetitiv."],"ok":[1],"why":"B – corect: antagonistul competitiv are afinitate pentru același situs și α = 0. A – fals: agonistul parțial are 0 < α < 1. C – fals: agonistul invers are activitate intrinsecă negativă (α < 0). D – fals: antagonistul necompetitiv se leagă de alt situs (alosteric).","src":"Curs UNIX Farmacologie · p. 36"},{"id":"unix_farma_c2_cs04","type":"mcq","topic":1,"diff":2,"hot":true,"q":"Prin ce se deosebește antagonistul necompetitiv de cel competitiv?","opts":["Are activitate intrinsecă negativă (α < 0).","Se leagă de același situs ca agonistul, dar cu afinitate mai mare.","Produce un efect identic cu al mediatorului.","Se leagă de un situs alosteric și blochează ireversibil."],"ok":[3],"why":"D – corect: necompetitivul are afinitate pentru alt situs (alosteric) și blochează ireversibil accesul mediatorului; competitivul ocupă același situs, reversibil. A – fals: α < 0 caracterizează agonistul invers. B – fals: necompetitivul nu se leagă de situsul agonistului. C – fals: efectul identic cu al mediatorului este al agonistului total.","src":"Curs UNIX Farmacologie · p. 36"},{"id":"unix_farma_c2_cs05","type":"mcq","topic":1,"diff":2,"hot":true,"q":"Ce ligand se comportă ca un antagonist competitiv atunci când este administrat împreună cu un agonist total?","opts":["Agonistul parțial.","Un antidot chelator, ex. EDTA.","Mediatorul endogen.","Antagonistul necompetitiv."],"ok":[0],"why":"A – corect: agonistul parțial ocupă receptorii și produce un efect mai mic decât ar fi produs agonistul total, deci în prezența acestuia se comportă ca un antagonist competitiv. B – fals: EDTA nu acționează pe receptor, ci prin antagonism chimic (complexarea metalelor grele). C – fals: mediatorul stimulează receptorul și produce efectul biologic. D – fals: necompetitivul acționează pe un situs alosteric, ireversibil.","src":"Curs UNIX Farmacologie · p. 37"},{"id":"unix_farma_c2_cs06","type":"mcq","topic":2,"diff":2,"hot":true,"q":"În prezența unui antagonist competitiv, curba doză-efect a agonistului total:","opts":["Rămâne neschimbată, deoarece antagonistul se leagă de alt situs.","Își păstrează poziția, dar efectul maxim scade.","Se deplasează la dreapta, paralel, cu același efect maxim.","Devine identică cu curba unui agonist parțial."],"ok":[2],"why":"C – corect: antagonistul competitiv ocupă reversibil același situs; crescând agonistul, îl „dai afară”, deci maximul se atinge din nou, la doze mai mari. A – fals: competitivul se leagă de același situs și modifică curba. B – fals: scăderea maximului apare la antagonistul necompetitiv. D – fals: curba agonistului parțial are maximul mai mic, iar competitivul nu scade maximul.","src":"Curs UNIX Farmacologie · p. 37"},{"id":"unix_farma_c2_cs07","type":"mcq","topic":2,"diff":2,"hot":true,"q":"Ce parametru este −log din concentrația molară de antagonist care face necesară creșterea de x ori a concentrației de agonist pentru același efect?","opts":["pD2.","pAx.","pD2'.","CE50."],"ok":[1],"why":"B – corect: pAx (pA2 este cazul particular al dublării concentrației de agonist); caracterizează antagonistul competitiv. A – fals: pD2 = −log CE50 și caracterizează agonistul total. C – fals: pD2' se referă la antagonistul necompetitiv care scade la jumătate efectul agonistului. D – fals: CE50 este parametrul agonistului total, nu al antagonistului.","src":"Curs UNIX Farmacologie · p. 37"},{"id":"unix_farma_c2_cs08","type":"mcq","topic":3,"diff":1,"hot":false,"q":"În cascada unui receptor cuplat cu proteine G, ce subunitate, legată de GTP, migrează intracelular și activează sau inactivează enzima care formează mesagerul secund?","opts":["Subunitatea β.","Subunitatea γ.","Complexul βγ.","Subunitatea α."],"ok":[3],"why":"D – corect: după disocierea αβγ, subunitatea α (cu GTP) migrează și acționează enzima efectoare. A, B, C – false: subunitățile β și γ (complexul βγ) sunt comune tuturor proteinelor G; cursul nu le atribuie acest rol.","src":"Curs UNIX Farmacologie · p. 40"},{"id":"unix_farma_c2_cs09","type":"mcq","topic":3,"diff":3,"hot":true,"q":"Sunt cuplați cu proteine Gs toți receptorii de mai jos, cu EXCEPȚIA:","opts":["Receptorii opioizi µ din SNC.","Receptorii β2-adrenergici presinaptici.","Receptorii H2 din celulele parietale gastrice.","Receptorii β3-adrenergici."],"ok":[0],"why":"A – corect (nu este Gs): receptorii µ sunt cuplați cu Gi. B – fals ca excepție: toți receptorii β sunt Gs, indiferent dacă sunt pre- sau postsinaptici. C – fals ca excepție: H2 este Gs (AMPc → secreție de HCl). D – fals ca excepție: β3 este tot Gs.","src":"Curs UNIX Farmacologie · p. 41"},{"id":"unix_farma_c2_cs10","type":"mcq","topic":3,"diff":2,"hot":false,"q":"Ce urmează legării ligandului de un receptor cu acțiune tirozin-kinazică?","opts":["Disocierea proteinei G în subunitatea α și complexul βγ.","Desprinderea proteinelor de șoc termic (HSP) de pe receptor.","Dimerizarea receptorului, cu activarea încrucișată a domeniilor tirozin-kinazice.","Deschiderea unui canal de Cl⁻, cu hiperpolarizare."],"ok":[2],"why":"C – corect: legare → dimerizare → activarea încrucișată a domeniilor tirozin-kinazice (receptor și efector în aceeași moleculă). A – fals: disocierea αβγ apare la receptorii cuplați cu proteine G. B – fals: desprinderea HSP apare la receptorii nucleari (citosolici). D – fals: canalul de Cl⁻ ține de receptorii ionotropi (GABA-A).","src":"Curs UNIX Farmacologie · p. 42"},{"id":"unix_farma_c2_cs11","type":"mcq","topic":4,"diff":1,"hot":false,"q":"Care dintre următorii liganzi NU acționează pe receptori nucleari (citosolici), conform cursului?","opts":["Hormonii tiroidieni.","Insulina.","Vitamina D.","Retinoizii."],"ok":[1],"why":"B – corect: receptorul insulinei este membranar, cu acțiune tirozin-kinazică. A, C, D – acționează pe receptori nemembranari (nucleari): cursul îi dă pentru steroizi, hormoni tiroidieni, vitaminele A și D, retinoizi (RXR, RAR).","src":"Curs UNIX Farmacologie · p. 43"},{"id":"unix_farma_c2_cs12","type":"mcq","topic":5,"diff":2,"hot":false,"q":"Ranitidina are efect antisecretor gastric deoarece, ca antagonist competitiv H2, împiedică în celula parietală:","opts":["Creșterea IP3 și DAG mediată de Gq.","Scăderea AMPc mediată de Gi.","Deschiderea canalelor de Cl⁻ cuplate cu receptorul.","Creșterea AMPc mediată de Gs, care activează pompa H⁺/K⁺."],"ok":[3],"why":"D – corect: histamina pe H2 (Gs) → AMPc → pompa H⁺/K⁺ → HCl; blocarea competitivă H2 oprește lanțul. A – fals: Gq / IP3-DAG sunt la α1, M1, M3. B – fals: H2 nu este Gi; Gi sunt α2, M2, µ. C – fals: canalele de Cl⁻ țin de GABA-A.","src":"Curs UNIX Farmacologie · p. 45"},{"id":"unix_farma_c2_cs13","type":"mcq","topic":5,"diff":3,"hot":false,"q":"Pentru anumiți compuși (ex. donorii de NO), structura receptoare este chiar:","opts":["Guanilat-ciclaza solubilă.","Adenilat-ciclaza membranară.","NO-sintaza endotelială.","Fosfolipaza C."],"ok":[0],"why":"A – corect: cursul precizează că guanilat-ciclaza solubilă poate fi chiar structura receptoare pentru donorii de NO (GTP → GMPc → miorelaxare). B – fals: adenilat-ciclaza formează AMPc, pe calea Gs/Gi. C – fals: NO-sintaza formează NO din arginină în endoteliu, nu este receptorul. D – fals: fosfolipaza C ține de calea Gq (IP3/DAG).","src":"Curs UNIX Farmacologie · p. 45"},{"id":"unix_farma_c2_cs14","type":"mcq","topic":6,"diff":2,"hot":true,"q":"De ce apare efectul rebound la oprirea bruscă a unui β-blocant administrat cronic?","opts":["Prin inactivarea receptorilor prin fosforilare.","Prin tahifilaxie, adică epuizarea mediatorilor.","Prin up-regulation: excesul cronic de antagonist a crescut numărul receptorilor β.","Prin autoinducție enzimatică."],"ok":[2],"why":"C – corect: excesul cronic de antagonist → up-regulation; la oprirea bruscă, receptorii mai numeroși dau rebound. A – fals: fosforilarea receptorilor este un mecanism de toleranță. B – fals: tahifilaxia este toleranță acută prin epuizarea mediatorilor. D – fals: autoinducția este mecanismul toleranței farmacocinetice.","src":"Curs UNIX Farmacologie · p. 46"},{"id":"unix_farma_c2_cs15","type":"mcq","topic":7,"diff":1,"hot":false,"q":"Asocierea dintre un deprimant central și un excitant central este un exemplu de:","opts":["Antagonism chimic.","Antagonism funcțional.","Antagonism farmacologic competitiv.","Sinergism de potențare."],"ok":[1],"why":"B – corect: antagonismul funcțional = efecte opuse prin mecanisme diferite (deprimante + excitante centrale). A – fals: antagonismul chimic înseamnă neutralizare sau complexare de către un antidot (ex. EDTA). C – fals: competitivul presupune același receptor. D – fals: potențarea crește răspunsul (ex. alcool + deprimante centrale), nu îl scade.","src":"Curs UNIX Farmacologie · p. 48"},{"id":"unix_farma_c2_cs16","type":"mcq","topic":7,"diff":3,"hot":false,"q":"Sunt exemple de sinergism supraaditiv (potențare) toate asocierile de mai jos, cu EXCEPȚIA:","opts":["Ampicilină + sulbactam.","Alcool + deprimante centrale.","Sulfametoxazol + trimetoprim.","Aspirină + paracetamol."],"ok":[3],"why":"D – corect (nu este potențare): asocierea analgezică aspirină + paracetamol este sinergism aditiv, E(AB) ≈ E(A) + E(B). A – potențare (penicilină + inhibitor de β-lactamază). B – potențare. C – potențare (co-trimoxazol).","src":"Curs UNIX Farmacologie · p. 48"},{"id":"unix_farma_c2_cs17","type":"mcq","topic":8,"diff":2,"hot":false,"q":"Glaucomul cortizonic, porfiria acută și deficitul de methemoglobin-reductază sunt, conform cursului, exemple de reacții:","opts":["Idiosincrazice.","Alergice de tip III.","Toxice, doză-dependente.","De tip D (delayed)."],"ok":[0],"why":"A – corect: cursul le listează la idiosincrazie (deficit enzimatic genetic, independent de doză, distribuție polimodală). B – fals: exemplele de tip III sunt boala serului, glomerulonefrita, vasculita, pneumonia cu eozinofilie. C – fals: reacțiile toxice au mecanism toxic direct, cu specificitate de organ. D – fals: exemplul de tip D este carcinogeneza la estrogeni.","src":"Curs UNIX Farmacologie · p. 51"},{"id":"unix_farma_c2_cs18","type":"mcq","topic":8,"diff":3,"hot":false,"q":"Despre tratamentul reacțiilor alergice medicamentoase, conform cursului, este FALSĂ afirmația:","opts":["În reacțiile de tip III se folosesc corticosteroizi.","În agranulocitoza medicamentoasă se oprește imediat medicația și se dau antibiotice bactericide.","În șocul anafilactic (tip I) se administrează hidrocortizon hemisuccinat 10–30 mg i.v.","În reacțiile de tip II se folosesc corticosteroizi."],"ok":[2],"why":"C – corect (afirmația e falsă): cursul dă în tipul I hidrocortizon hemisuccinat 100–300 mg i.v., nu 10–30 mg. A – adevărat: tipul III se tratează cu corticosteroizi. B – adevărat: la agranulocitoză / aplazie se oprește imediat medicația și se dau antibiotice bactericide (plus transfuzie). D – adevărat: la tipul II, corticosteroizi.","src":"Curs UNIX Farmacologie · p. 50"},{"id":"unix_farma_c2_cs19","type":"mcq","topic":8,"diff":2,"hot":true,"q":"Dependența psihică se definește prin:","opts":["Apariția sindromului de abstinență la întreruperea substanței.","Constrângerea de a consuma substanța pentru o satisfacție emoțională, cu implicarea centrilor recompensei.","Răspunsul exagerat la doza terapeutică.","Necesitatea creșterii progresive a dozei pentru același efect."],"ok":[1],"why":"B – corect: definiția din curs (euforie, halucinații; hipotalamus latero-anterior, aria septală, amigdala, arii talamice, ganglionii bazali). A – fals: sindromul de abstinență definește dependența fizică. C – fals: răspunsul exagerat este intoleranța. D – fals: aceasta este toleranța (stare de hiporeactivitate).","src":"Curs UNIX Farmacologie · p. 53"},{"id":"unix_farma_c2_cs20","type":"mcq","topic":8,"diff":3,"hot":false,"q":"Pneumonia cu eozinofilie de cauză medicamentoasă este, conform cursului, o reacție alergică de tip:","opts":["I (anafilactic).","II (citotoxic).","IV (întârziat).","III (complexe imune)."],"ok":[3],"why":"D – corect: cursul o dă la tipul III, alături de boala serului, glomerulonefrită și vasculită (complexe Ag-Ac → complement → obstrucția vaselor mici). A – fals: exemplele de tip I sunt șocul anafilactic, astmul la aspirină/AINS, edemul Quincke. B – fals: tipul II = anemie hemolitică, trombocitopenie, agranulocitoză, anemie aplastică, sindrom lupoid. C – fals: tipul IV = dermatita de contact, rash-ul neurticarian.","src":"Curs UNIX Farmacologie · p. 50"},{"id":"unix_farma_c2_cs21","type":"mcq","topic":8,"diff":2,"hot":false,"q":"Despre riscurile medicamentelor asupra fătului, nou-născutului și reproducerii sunt adevărate:","opts":["Riscul fetal apare după încheierea organogenezei (trimestrele II–III) și afectează creșterea și maturarea histologică și enzimatică.","Riscul neonatal ține de medicația ante partum și de căile de epurare insuficient dezvoltate ale nou-născutului.","Teratogeneza indirectă poate fi produsă de substanțe care scad fluxul sanguin placentar, de ocitocice și de hormoni.","Alchilanții și griseofulvina pot fi carcinogeni prin alterarea ADN și activarea oncogenelor.","Androgenii și steroizii anabolizanți afectează spermatogeneza la început reversibil, apoi ireversibil."],"ok":[0,1,2,3,4],"why":"Toate 5 – corecte, după tabelul și casetele din curs: riscul fetal = agresiune funcțională (efecte toxice, nu teratogene) după organogeneză; riscul neonatal = medicația ante partum + epurare imatură; teratogeneza indirectă = ↓ flux placentar, ocitocice, hormoni; carcinogeneza prin alterarea ADN / oncogene (alchilanți, griseofulvină); spermatogeneza: androgeni, steroizi anabolizanți, citotoxice = reversibil, apoi ireversibil.","src":"Curs UNIX Farmacologie · p. 52"},{"id":"unix_farma_c2_cs22","type":"mcq","topic":8,"diff":3,"hot":false,"q":"Despre reacțiile toxice ale medicamentelor sunt adevărate:","opts":["Izoniazida, etambutolul și metronidazolul pot produce polinevrite.","Steroizii 17-α-alchilați și rifampicina pot produce icter.","Fenotiazinele, ADO și eritromicina pot produce colestază.","Neurolepticele pot produce, la nivelul SNC, diskinezie tardivă.","Toxicitatea acută se exprimă prin DL50."],"ok":[0,1,2,3,4],"why":"Toate 5 – corecte, din coloana „Toxic” a cursului: polinevrite (izoniazidă, etambutol, metronidazol); icter (steroizi 17-α-alchilați, rifampicină); colestază (fenotiazine, ADO, eritromicină); SNC: neuroleptice → diskinezie tardivă; toxicitatea acută: DL50.","src":"Curs UNIX Farmacologie · p. 51"}]});
